7	// order of magnitude (to a max order)
8	func oomm(n, b *big.Int, maxmag int) (float64, int) {
9		mag := 0
10		m := &big.Int{}
11		for n.Cmp(b) >= 0 {
12			n.DivMod(n, b, m)
13			mag++
14			if mag == maxmag && maxmag >= 0 {
15				break
16			}
17		}
18		return float64(n.Int64()) + (float64(m.Int64()) / float64(b.Int64())), mag
19	}
