22	// (same as above, but with no upper limit)
23	func oom(n, b *big.Int) (float64, int) {
24		mag := 0
25		m := &big.Int{}
26		for n.Cmp(b) >= 0 {
27			n.DivMod(n, b, m)
28			mag++
29		}
30		return float64(n.Int64()) + (float64(m.Int64()) / float64(b.Int64())), mag
